const BG_URLS:any={Office:"https://images.unsplash.com/photo-1497366216548-37526070297c?w=800",Kitchen:"https://images.unsplash.com/photo-1556911220-bff31c812dba?w=800",Beach:"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800",Night:"https://images.unsplash.com/photo-1519681393784-d120267933ba?w=800",Party:"https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=800",Home:"https://images.unsplash.com/photo-1567016432779-094069958ea5?w=800",Blur:""};
function getFilterStyle(filter:string,beauty:number){let f="";if(filter==="Warm")f="sepia(0.3) saturate(1.4)";if(filter==="Cool")f="hue-rotate(15deg) saturate(1.2)";if(filter==="Black & White")f="grayscale(1)";if(filter==="Vivid")f="saturate(1.8) contrast(1.1)";if(filter==="Soft")f="brightness(1.1) contrast(0.95) saturate(0.9)";if(beauty>0)f+=(f?" ":"")+"brightness("+(1+beauty*0.04)+") contrast("+(1-beauty*0.02)+") saturate("+(1+beauty*0.03)+")";return f||"none"}
async function loadSegmentation(){if(segRef.current)return segRef.current;setBgLoading(true);try{await new Promise((res,rej)=>{if((window as any).SelfieSegmentation){res(0);return}const s=document.createElement("script");s.src="https://cdn.jsdelivr.net/npm/@mediapipe/selfie_segmentation/selfie_segmentation.js";s.onload=()=>res(0);s.onerror=()=>rej(0);document.head.appendChild(s)});const seg=new (window as any).SelfieSegmentation({locateFile:(f:string)=>"https://cdn.jsdelivr.net/npm/@mediapipe/selfie_segmentation/"+f});seg.setOptions({modelSelection:1});segRef.current=seg;setBgLoading(false);return seg}catch(e){setBgLoading(false);return null}}
function drawRealBg(canvas:any,video:any,bgName:string,filter:string,beauty:number,segMask:any){if(!canvas||!video||video.videoWidth===0)return;const ctx=canvas.getContext("2d");if(canvas.width!==video.videoWidth)canvas.width=video.videoWidth;if(canvas.height!==video.videoHeight)canvas.height=video.videoHeight;ctx.save();ctx.filter=getFilterStyle(filter,beauty);if(bgName==="None"||!segMask){ctx.drawImage(video,0,0,canvas.width,canvas.height);ctx.restore();return}if(bgName==="Blur"){ctx.filter="blur(12px) brightness(0.9)";ctx.drawImage(video,0,0,canvas.width,canvas.height);ctx.filter=getFilterStyle(filter,beauty);ctx.drawImage(segMask,0,0,canvas.width,canvas.height);ctx.globalCompositeOperation="destination-in";ctx.drawImage(video,0,0,canvas.width,canvas.height);ctx.restore();ctx.globalCompositeOperation="source-over";return}const img=bgImgRef.current;if(!img||img._bg!==bgName){const nImg=new Image();nImg.crossOrigin="anonymous";nImg._bg=bgName;nImg.src=BG_URLS[bgName]||"";bgImgRef.current=nImg;ctx.drawImage(video,0,0,canvas.width,canvas.height);ctx.restore();return}ctx.drawImage(img,0,0,canvas.width,canvas.height);ctx.drawImage(segMask,0,0,canvas.width,canvas.height);ctx.globalCompositeOperation="destination-in";ctx.drawImage(video,0,0,canvas.width,canvas.height);ctx.restore();ctx.globalCompositeOperation="source-over"}
async function startSegLoop(videoEl:any,canvasEl:any,getBg:()=>string,getFilter:()=>string,getBeauty:()=>number){const seg=await loadSegmentation();if(!seg)return;if(segRafRef.current)cancelAnimationFrame(segRafRef.current);let lastMask:any=null;seg.onResults((res:any)=>{if(res.segmentationMask)lastMask=res.segmentationMask;drawRealBg(canvasEl,videoEl,getBg(),getFilter(),getBeauty(),lastMask)});const loop=async()=>{if(!videoEl||videoEl.paused||videoEl.ended||videoEl.videoWidth===0){segRafRef.current=requestAnimationFrame(loop);return}try{await seg.send({image:videoEl})}catch(e){}segRafRef.current=requestAnimationFrame(loop)};loop()}
function stopSegLoop(){if(segRafRef.current)cancelAnimationFrame(segRafRef.current);segRafRef.current=null}
