async function toggleTorch(){const stream=liveStreamRef.current||streamRef.current;if(!stream){alert("Pehle Back Camera kholein! Front camera par Torch nahi hoti!");return}const track=stream.getVideoTracks()[0];if(!track){alert("Camera track nahi mila!");return}if(facingMode==="user"){alert("Torch sirf Back Camera par chalti hai! Pehle 🔄 se Back Camera karein, phir Torch On karein!");return}try{const caps:any=track.getCapabilities&&track.getCapabilities();if(caps&&!caps.torch){alert("Is phone me Torch support nahi hai!");return}await track.applyConstraints({advanced:[{torch:!torchOn} as any]});setTorchOn(!torchOn);if(!torchOn)alert("Torch ON ho gayi! 🔦");}catch(e){alert("Torch On nahi hui! Ye phone Torch support nahi karta ya Back Camera par nahi hai!")}}
