async function loadGifs(cat:string){if(cat==="My GIFs"){setLiveGifs(myGifs);return}const q=gifQuery[cat]||cat;setGifLoading(true);try{const r=await fetch("https://tenor.googleapis.com/v2/search?q="+encodeURIComponent(q)+"&key=LIVDSRZULELA&limit=24&media_filter=gif");const d=await r.json();if(d.results&&d.results.length){const urls=d.results.map((x:any)=>x.media_formats?.gif?.url||x.media_formats?.tinygif?.url).filter(Boolean);if(urls.length){setLiveGifs(urls);setGifLoading(false);return}}}catch(e){}setLiveGifs(fallbackGifs);setGifLoading(false)}
