function getRealLocation(sendLive=false){if(!navigator.geolocation){alert("GPS not available!");return}navigator.geolocation.getCurrentPosition((pos)=>{const lat=pos.coords.latitude;const lng=pos.coords.longitude;setShowAttach(false);pushMsg({type:"location",lat,lng,live:sendLive,mapUrl:"https://www.google.com/maps?q="+lat+","+lng,embedUrl:"https://www.openstreetmap.org/export/embed.html?bbox="+(lng-0.01)+","+(lat-0.01)+","+(lng+0.01)+","+(lat+0.01)+"&layer=mapnik&marker="+lat+","+lng});if(sendLive)startLiveLocation()},(err)=>{alert("Please allow Location permission!")},{enableHighAccuracy:true,timeout:10000})}
function startLiveLocation(){setLiveLoc(true);if(liveLocTimer.current)clearInterval(liveLocTimer.current);liveLocTimer.current=setInterval(()=>{navigator.geolocation.getCurrentPosition((pos)=>{const lat=pos.coords.latitude;const lng=pos.coords.longitude;pushMsg({type:"location",lat,lng,live:true,mapUrl:"https://www.google.com/maps?q="+lat+","+lng,embedUrl:"https://www.openstreetmap.org/export/embed.html?bbox="+(lng-0.01)+","+(lat-0.01)+","+(lng+0.01)+","+(lat+0.01)+"&layer=mapnik&marker="+lat+","+lng})})},30000);setTimeout(()=>{setLiveLoc(false);if(liveLocTimer.current)clearInterval(liveLocTimer.current)},15*60*1000)}
function onAudioFile(e:any){const f=e.target.files[0];if(!f)return;const reader=new FileReader();reader.onloadend=()=>{pushMsg({type:"audiofile",url:reader.result,name:f.name,size:(f.size/1024/1024).toFixed(2)+" MB"})};reader.readAsDataURL(f);setShowAttach(false)}
function onGalleryPick(e:any){const files=Array.from(e.target.files||[]);if(!files.length)return;const items=(files as any[]).map((f:any)=>({type:f.type.startsWith("video")?"video":"photo",url:URL.createObjectURL(f),time:"Now"}));if(items.length===1)pushMsg(items[0]);else pushMsg({type:"collage",items,time:"Now"});setShowCameraChoice(false);setShowAttach(false)}
function onDocumentPick(e:any){const f=e.target.files[0];if(!f)return;pushMsg({type:"text",text:"Document: "+f.name});setShowAttach(false)}
async function openLiveCamera(){setShowCameraChoice(false);setShowAttach(false);setShowLiveCamera(true);setCapturedPhoto("");setCameraMode("photo");setBgEffect("None");setFilterEffect("None");setBeautyLevel(0);setFacingMode("user");setTorchOn(false);try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user"},audio:true});liveStreamRef.current=stream;setTimeout(()=>{if(liveVideoRef.current){liveVideoRef.current.srcObject=stream;liveVideoRef.current.play();if(bgEffect!=="None")startSegLoop(liveVideoRef.current,segCanvasRef.current,()=>bgEffect,()=>filterEffect,()=>beautyLevel)}},300)}catch(e){alert("Please allow Camera permission!");setShowLiveCamera(false)}}
async function flipCamera(){if(isFlipping)return;setIsFlipping(true);const nf=facingMode==="user"?"environment":"user";try{stopSegLoop();const old1=liveStreamRef.current;const old2=streamRef.current;if(old1)old1.getTracks().forEach((t:any)=>{try{t.stop()}catch(e){}});if(old2)old2.getTracks().forEach((t:any)=>{try{t.stop()}catch(e){}});if(liveVideoRef.current)liveVideoRef.current.srcObject=null;if(videoRef.current)videoRef.current.srcObject=null;setTorchOn(false);await new Promise(r=>setTimeout(r,350));let stream=null;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{exact:nf}},audio:true})}catch(e){try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:nf},audio:true})}catch(e2){stream=await navigator.mediaDevices.getUserMedia({video:true,audio:true})}}setFacingMode(nf);liveStreamRef.current=stream;streamRef.current=stream;if(showLiveCamera&&liveVideoRef.current){liveVideoRef.current.srcObject=stream;await liveVideoRef.current.play().catch(()=>{})}if(call&&videoRef.current){videoRef.current.srcObject=stream;await videoRef.current.play().catch(()=>{})}}catch(e){alert("Back Camera nahi khula! Dobara try karein!");try{const s2=await navigator.mediaDevices.getUserMedia({video:{facingMode:"user"},audio:true});setFacingMode("user");liveStreamRef.current=s2;streamRef.current=s2;if(liveVideoRef.current){liveVideoRef.current.srcObject=s2;liveVideoRef.current.play()}if(videoRef.current){videoRef.current.srcObject=s2;videoRef.current.play()}}catch(e){}}setIsFlipping(false)}
function closeLiveCamera(){stopSegLoop();setTorchOn(false);if(liveStreamRef.current){liveStreamRef.current.getTracks().forEach((t:any)=>t.stop());liveStreamRef.current=null}setShowLiveCamera(false);setCapturedPhoto("");setIsVideoRec(false);setShowEffects(false);if(recTimerSecRef.current)clearInterval(recTimerSecRef.current);setRecTimerSec(0)}
function capturePhoto(){const src=bgEffect!=="None"?segCanvasRef.current:liveVideoRef.current;if(!src)return;const c=liveCanvasRef.current;if(!c)return;c.width=src.videoWidth||src.width;c.height=src.videoHeight||src.height;const ctx=c.getContext("2d");ctx.drawImage(src,0,0);setCapturedPhoto(c.toDataURL("image/jpeg",0.9))}
function sendCapturedPhoto(){if(!capturedPhoto)return;pushMsg({type:"photo",url:capturedPhoto});closeLiveCamera()}
function startVideoRec(){if(!liveStreamRef.current)return;videoChunks.current=[];const rec=new MediaRecorder(liveStreamRef.current);videoRecRef.current=rec;rec.ondataavailable=(e:any)=>{if(e.data.size>0)videoChunks.current.push(e.data)};rec.onstop=()=>{const blob=new Blob(videoChunks.current,{type:"video/webm"});const reader=new FileReader();reader.onloadend=()=>{pushMsg({type:"video",url:reader.result})};reader.readAsDataURL(blob);closeLiveCamera()};rec.start();setIsVideoRec(true);setRecTimerSec(0);if(recTimerSecRef.current)clearInterval(recTimerSecRef.current);recTimerSecRef.current=setInterval(()=>setRecTimerSec(t=>t+1),1000)}
function stopVideoRec(){if(videoRecRef.current&&isVideoRec){try{videoRecRef.current.stop()}catch(e){}setIsVideoRec(false)}if(recTimerSecRef.current)clearInterval(recTimerSecRef.current)}
function toggleVoicePlay(idx:number,url:string){if(playingIdx===idx){if(audioRef.current)audioRef.current.pause();setPlayingIdx(null);return}if(audioRef.current)audioRef.current.pause();const a=new Audio(url);audioRef.current=a;a.ontimeupdate=()=>{if(a.duration)setAudioProgress((a.currentTime/a.duration)*100)};a.onended=()=>{setPlayingIdx(null);setAudioProgress(0)};a.play();setPlayingIdx(idx)}
async function startRecording(e:any){if(recording||locked)return;if(isBlocked)return;if(e){e.preventDefault();e.stopPropagation()}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const rec=new MediaRecorder(stream);recRef.current=rec;recChunks.current=[];rec.ondataavailable=(ev:any)=>{if(ev.data.size>0)recChunks.current.push(ev.data)};rec.start(250);setRecording(true);setRecTime(0);setRecHint("");if(recTimer.current)clearInterval(recTimer.current);recTimer.current=setInterval(()=>setRecTime(t=>t+1),1000)}catch(err){alert("Mic permission dein!");setRecording(false)}}
function onMicMove(e:any){if(!recording||locked)return;const t=e.touches?e.touches[0]:e;if(!t)return;const dx=t.clientX-startX.current;const dy=t.clientY-startY.current;if(dx<-60){isCancel.current=true;setRecHint("← Choro to Cancel")}else if(dy<-60){setRecHint("↑ Choro to Lock")}else{isCancel.current=false;setRecHint("")}}
function onMicRelease(e:any){if(!recording)return;if(e)e.preventDefault();const endX=e.changedTouches?e.changedTouches[0].clientX:e.clientX||0;const endY=e.changedTouches?e.changedTouches[0].clientY:e.clientY||0;const dx=endX-startX.current;const dy=endY-startY.current;if(dy<-60){setLocked(true);setRecHint("Locked");return}if(locked)return;if(isCancel.current||dx<-60){finishRecording(false)}else{finishRecording(true)}}
function finishRecording(sendIt:boolean){if(!recRef.current)return;if(recTimer.current)clearInterval(recTimer.current);const rec=recRef.current;const curTime=recTime;rec.onstop=()=>{try{if(rec.stream)rec.stream.getTracks().forEach((t:any)=>t.stop())}catch(e){}if(sendIt&&curTime>0&&recChunks.current.length){const blob=new Blob(recChunks.current,{type:"audio/webm"});const reader=new FileReader();reader.onloadend=()=>{pushMsg({type:"voice",url:reader.result,duration:formatTime(curTime)})};reader.readAsDataURL(blob)}};try{if(rec.state!=="inactive")rec.stop()}catch(e){}setRecording(false);setLocked(false);setRecHint("");isCancel.current=false;setRecTime(0)}
function send(){if(!txt||isBlocked)return;const nm:any={type:"text",text:txt};if(replyTo)nm.reply=replyTo.text||replyTo;pushMsg(nm);setTxt("");setEmojiPanel(false);setReplyTo(null)}
